 @GetMapping("/warehouses") public ApiResponse<?> operation22(@RequestParam(name="page",defaultValue="0") int page,@RequestParam(name="size",defaultValue="20") int size,@RequestParam(name="keyword",required=false) String keyword,@RequestParam Map<String,String> filters){return ApiResponse.success(service.list("Warehouse",page,size,keyword,filters),traces.currentTraceId());}
 @PostMapping("/warehouses") public ApiResponse<?> operation23(@RequestBody WarehouseCreate body,@RequestHeader("Idempotency-Key") String key){return ApiResponse.success(service.maintenance("Warehouse",null,body,null,key),traces.currentTraceId());}
 @GetMapping("/warehouses/{id}") public ApiResponse<?> operation24(@PathVariable("id") String id){return ApiResponse.success(service.get("Warehouse",id),traces.currentTraceId());}
 @PutMapping("/warehouses/{id}") public ApiResponse<?> operation25(@PathVariable("id") String id,@RequestBody WarehouseUpdate body,@RequestHeader("Idempotency-Key") String key,@RequestHeader(name="If-Match",required=false) String version){return ApiResponse.success(service.maintenance("Warehouse",id,body,version,key),traces.currentTraceId());}
 @GetMapping("/wms/receipts") public ApiResponse<?> operation26(@RequestParam(name="page",defaultValue="0") int page,@RequestParam(name="size",defaultValue="20") int size,@RequestParam(name="keyword",required=false) String keyword,@RequestParam Map<String,String> filters){return ApiResponse.success(service.list("Receipt",page,size,keyword,filters),traces.currentTraceId());}
 @PostMapping("/wms/receipts") public ApiResponse<?> operation27(@RequestBody ReceiptCreate body,@RequestHeader("Idempotency-Key") String key){return ApiResponse.success(service.createReceipt(body,key,false),traces.currentTraceId());}
