 @PostMapping("/wms/receipts/{id}/confirm") public ApiResponse<?> operation29(@PathVariable("id") String id,@RequestBody Command body,@RequestHeader("Idempotency-Key") String key,@RequestHeader(name="If-Match",required=false) String version){return ApiResponse.success(service.confirmReceipt(id,body,version,key),traces.currentTraceId());}
 @GetMapping("/wms/material-lots") public ApiResponse<?> operation30(@RequestParam(name="page",defaultValue="0") int page,@RequestParam(name="size",defaultValue="20") int size,@RequestParam(name="keyword",required=false) String keyword,@RequestParam Map<String,String> filters){return ApiResponse.success(service.list("MaterialLot",page,size,keyword,filters),traces.currentTraceId());}
 @GetMapping("/wms/material-lots/{id}") public ApiResponse<?> operation31(@PathVariable("id") String id){return ApiResponse.success(service.get("MaterialLot",id),traces.currentTraceId());}
 @PutMapping("/wms/receipts/{id}") public ApiResponse<?> operation32(@PathVariable("id") String id,@RequestBody ReceiptUpdate body,@RequestHeader("Idempotency-Key") String key,@RequestHeader(name="If-Match",required=false) String version){return ApiResponse.success(service.updateReceipt(id,body,version,key),traces.currentTraceId());}
